import React from 'react';

const Header = () => {
  return (
    <header className="bg-white shadow-sm py-4">
      <div className="container mx-auto flex justify-between items-center px-4">
        <div className="logo text-2xl font-bold text-primary-blue">
          <a href="/" className="hover:text-blue-700">Stag.io</a>
        </div>
        <nav className="flex items-center space-x-6">
          <ul className="hidden md:flex space-x-6">
            <li><a href="#how-it-works" className="text-text-grey hover:text-primary-blue transition-colors duration-200">How it Works</a></li>
            <li><a href="#about-us" className="text-text-grey hover:text-primary-blue transition-colors duration-200">About Us</a></li>
            <li><a href="#contact-us" className="text-text-grey hover:text-primary-blue transition-colors duration-200">Contact Us</a></li>
          </ul>
          <div className="flex space-x-3">
            <button className="btn btn-secondary">Login</button>
            <button className="btn btn-primary">Sign Up</button>
          </div>
        </nav>
        {/* Mobile menu button could go here if you want to implement a hamburger menu */}
      </div>
    </header>
  );
};

export default Header;
